 private final ExecutorService work=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final StoryMediaExporter exporter=new StoryMediaExporter();
 private StoryCanvasView canvas;private ReelTrimTimelineView timeline;private PlayerView playerView;private ExoPlayer player;private ReelPlaybackMonitor monitor;private ImageView exportedPreview;private Bitmap sourceBitmap;
 private TextView status;private EditText caption;private Button publish,privacy;private CheckBox mute;private ProgressBar progress;
 private String pendingUri;private String appliedBase;private File folder,source,output;private String mime,audience="followers",asset,frozenCaption,frozenAudience;private long duration,start,end,position;private boolean busy,previewing,resumed,disposed,brushMode;private int generation;private SupabaseStorage.Transfer transfer;private Subscription createRequest;
 private final ActivityResultLauncher<PickVisualMediaRequest> picker=registerForActivityResult(new ActivityResultContracts.PickVisualMedia(),uri->{if(uri!=null)stage(uri);});
